code_sketch:
export class Name {
  @Column() first: string;
  @Column() last: string;
}

@Entity()
export class User {
  @PrimaryGeneratedColumn() id: string;
  @Column(() => Name) name: Name;   // merges to nameFirst / nameLast
  @Column() isActive: boolean;
}

